const MARKER = '.bundled-skills.json';

/**
 * Puts the bundled skills into a project's `.claude/skills` folder. A skill is written once: the names already seeded are kept in
 * a marker file, so a skill someone edited is never overwritten and one they deleted does not come back. Never throws.
 * Returns the names written this time.
 */
export async function ensureBundledSkills(projectDir: string): Promise<string[]> {
  const written: string[] = [];
  try {
    const skillsDir = path.join(projectDir, '.claude', 'skills');
    await fsp.mkdir(skillsDir, { recursive: true });
    const markerFile = path.join(skillsDir, MARKER);
    if (!fs.existsSync(markerFile)) await restoreFile(markerFile).catch(() => false);
    let seeded: string[] = [];
    try { const v = JSON.parse(fs.readFileSync(markerFile, 'utf8')) as unknown; if (Array.isArray(v)) seeded = v.filter((n): n is string => typeof n === 'string'); } catch { /* none yet */ }

    for (const skill of BUNDLED_SKILLS) {
      if (seeded.includes(skill.name)) continue;
      const dir = path.join(skillsDir, skill.name);
      // A folder that is already there (someone made a skill of this name) is theirs: leave it alone.
      if (!fs.existsSync(dir)) {
        await fsp.mkdir(dir, { recursive: true });
        for (const [file, content] of Object.entries(skill.files)) {
          const target = path.join(dir, file);
          await fsp.writeFile(target, content, 'utf8');
          await persistFile(target, file.endsWith('.md') ? 'text/markdown' : 'text/plain').catch(() => undefined);
        }
        written.push(skill.name);
      }
      seeded.push(skill.name);
    }
    if (seeded.length) {
      await fsp.writeFile(markerFile, JSON.stringify(seeded), 'utf8');
      await persistFile(markerFile, 'application/json').catch(() => undefined);
    }
  } catch (err) {
    console.warn('[bundled-skills] could not seed the bundled skills:', err instanceof Error ? err.message : err);
  }
  return written;
}
